changeSet.sql:
CREATE MATERIALIZED VIEW mv_daily_recon_summary AS SELECT t.trade_date, c.region, i.asset_class, COUNT(*) AS total_trades, COUNT(*) FILTER (WHERE t.status = 'MATCHED') AS matched_trades, COUNT(*) FILTER (WHERE rb.status = 'OPEN') AS open_breaks, COALESCE(ROUND(SUM(t.quantity * t.price)::numeric, 2), 0) AS gross_notional, CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND((COUNT(*) FILTER (WHERE t.status = 'MATCHED')::numeric * 100.0) / COUNT(*)::numeric, 2) END AS match_rate_pct FROM trades t JOIN counterparties c ON c.id = t.counterparty_id JOIN instruments i ON i.id = t.instrument_id LEFT JOIN recon_breaks rb ON rb.trade_id = t.id WHERE deleted_at IS NULL GROUP BY t.trade_date, c.region, i.asset_class WITH NO DATA;
CREATE UNIQUE INDEX uq_mv_daily_recon_summary ON mv_daily_recon_summary (trade_date, region, asset_class);
CREATE INDEX idx_mv_daily_recon_summary_region ON mv_daily_recon_summary (region);
CREATE INDEX idx_mv_daily_recon_summary_trade_date ON mv_daily_recon_summary (trade_date);
